const $=s=>document.querySelector(s);
function theme(dark){document.body.classList.toggle('dark',dark);$('#theme').textContent=dark?'☀':'☾'}
try{theme(localStorage.getItem('robot-theme')==='dark')}catch{}
$('#theme').addEventListener('click',()=>{theme(!document.body.classList.contains('dark'));try{localStorage.setItem('robot-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}});
for(const button of document.querySelectorAll('.load-video'))button.addEventListener('click',()=>{const url=new URL(button.dataset.embed);if(url.protocol!=='https:'||url.hostname!=='www.youtube-nocookie.com')return;const frame=document.createElement('iframe');frame.src=url.href;frame.title=button.dataset.title;frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';button.replaceWith(frame);frame.focus()});
for(const img of document.querySelectorAll('.article-figure img'))img.addEventListener('error',()=>{img.hidden=true;const note=document.createElement('p');note.className='media-error';note.textContent='รูปนี้โหลดไม่ได้ในขณะนี้ เปิดดูภาพขนาดเต็มจากลิงก์ด้านล่างได้';img.parentElement.append(note)},{once:true});
for(const video of document.querySelectorAll('video')){const failure=()=>{if(video.parentElement.querySelector('.media-error'))return;const p=document.createElement('p');p.className='media-error';p.textContent='ไม่สามารถเล่นวิดีโอนี้ได้ กรุณาเปิดวิดีโอต้นฉบับด้านล่าง';video.after(p)};video.addEventListener('error',failure);video.querySelector('source')?.addEventListener('error',failure)}
$('#share-article').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);$('#toast').textContent='คัดลอกลิงก์ข่าวแล้ว';$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2400)}catch{const input=document.createElement('input');input.value=location.href;input.readOnly=true;input.setAttribute('aria-label','ลิงก์ข่าวสำหรับคัดลอก');$('#share-article').after(input);input.select()}});
